<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
class Supplier extends Model { use HasUuids; protected $fillable = ['tenant_id','company_id','name','trading_name','code','supplier_type','category','email','phone','alternative_phone','address','tax_identifier','business_registration_number','website','description','contact_person_name','contact_person_job_title','contact_person_email','contact_person_phone','preferred_currency_id','payment_terms','preferred_communication_method','internal_notes','status','archived_at','created_by','updated_by']; protected function casts():array{return ['archived_at'=>'datetime'];} public function company(){return $this->belongsTo(Company::class);} public function currency(){return $this->belongsTo(AccountingCurrency::class,'preferred_currency_id');} public function contacts(){return $this->hasMany(SupplierContact::class);} public function addresses(){return $this->hasMany(SupplierAddress::class);} public function purchaseOrders(){return $this->hasMany(PurchaseOrder::class);} public function bills(){return $this->hasMany(SupplierBill::class);} }
